from pathlib import Path
import re
files = [Path('Home.md'), Path('docs/README.md'), Path('agents/README.md'), Path('remark/README.md')]
missing=[]
for p in files:
    text=p.read_text()
    for raw in re.findall(r'\[\[([^\]|#]+)(?:[#|][^\]]*)?\]\]', text):
        target=Path(raw)
        candidates=[target, target.with_suffix('.md')]
        if not any(c.exists() for c in candidates):
            missing.append((str(p), raw))
if missing:
    for p, raw in missing:
        print(f'MISSING {p}: {raw}')
    raise SystemExit(1)
print('All wiki-link file targets exist')
